import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.vLhlLNVn.js";const b=JSON.parse('{"title":"Flashen per USB","description":"","frontmatter":{"order":7},"headers":[],"relativePath":"de/adapter/esphome/flashbinary.md","filePath":"de/adapter/esphome/flashbinary.md","lastUpdated":1794652328000}'),l={name:"de/adapter/esphome/flashbinary.md"};function o(r,e,n,p,h,d){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="flashen-per-usb" tabindex="-1">Flashen per USB <a class="header-anchor" href="#flashen-per-usb" aria-label="Permalink to &quot;Flashen per USB&quot;">​</a></h1><p>Das Flashen einer *.binary auf einen ESP-Chipsatz ist recht einfach, wenn Sie die richtigen Tools verwenden. Es gibt mehrere Möglichkeiten, ich persönlich empfehle die Verwendung des esptool flasher.</p><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Offizieller Download und Anleitung</p><p><a href="https://github.com/espressif/esptool" target="_blank" rel="noreferrer">espressif/esptool</a></p></div><h2 id="mac" tabindex="-1">Mac <a class="header-anchor" href="#mac" aria-label="Permalink to &quot;Mac&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Verwenden Sie brew, um die Abhängigkeiten zu erhalten</p><p><a href="https://brew.sh" target="_blank" rel="noreferrer">Brew holen und installieren</a> Installieren Sie python <code>brew install python`` Installieren Sie esptool </code>brew install esptool``<br> Siehe für weitere Informationen <a href="https://docs.brew.sh/Homebrew-and-Python" target="_blank" rel="noreferrer">Homebrew Dokumentation</a></p></div><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">esptool.exe ist im ESPEasy-Paket enthalten</p><p>Holen Sie es sich von <a href="https://github.com/letscontrolit/ESPEasy/files/5566286/esp32tool-initial-flashing.zip" target="_blank" rel="noreferrer">lets control it</a><br> Eine alternative recht gute Anleitung finden Sie bei <a href="https://cyberblogspot.com/how-to-install-esptool-on-windows-10/" target="_blank" rel="noreferrer">cyberblogspot</a></p></div><h2 id="flash-befehle" tabindex="-1">Flash-Befehle <a class="header-anchor" href="#flash-befehle" aria-label="Permalink to &quot;Flash-Befehle&quot;">​</a></h2><p>Der Befehl esptool.py flasht den Speicher eines ESP8266:</p><p><code>esptool.py --port [serial-port-of-ESP8266] write_flash -fm dio -fs detect 0x00000 &gt;nodemcu-firmware&lt;.bin</code></p><h2 id="esp32-bootloader" tabindex="-1">ESP32-Bootloader <a class="header-anchor" href="#esp32-bootloader" aria-label="Permalink to &quot;ESP32-Bootloader&quot;">​</a></h2><p>Für ESP32 müssen Sie das Flash löschen, das Binary UND den Bootloader laden!</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Ge die benötigten Dateien aus <a href="https://github.com/letscontrolit/ESPEasy/files/5566286/esp32tool-initial-flashing.zip" target="_blank" rel="noreferrer">lets control it</a></p></div><ol><li>Löschen Sie das Flash</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>esptool.py--chip esp32 --port COM8 --baud 256000 --before default_reset --after hard_reset erase_flash</span></span></code></pre></div><ol start="2"><li>Flashen der Binärdatei</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>esptool.py --chip esp32 --port COM8 --baud 256000 --before default_reset --after hard_reset write_flash -z --flash_mode dio --flash_freq 80m --flash_size detect 0x10000 &gt;binaryName&lt;.bin</span></span></code></pre></div><ol start="3"><li>Flash-Bootloader und Partitionen</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>esptool.py --chip esp32 --port COM8 --baud 256000 --before default_reset --after hard_reset write_flash -z --flash_mode dio --flash_freq 80m --flash_size detect 0x8000 ./initial-images/partitions2.bin 0xe000 ./initial-images/boot_app0.bin 0x1000 ./initial-images/bootloader.bin</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Ersetzen Sie esptool.py durch die richtige ausführbare Datei, z.B. esptool.exe (Windows) oder esp32tool.py/exe bei Verwendung von <a href="https://github.com/letscontrolit/ESPEasy/files/5566286/esp32tool-initial-flashing.zip" target="_blank" rel="noreferrer">lets control it librarys</a></p></div>',21)])])}const f=a(l,[["render",o]]);export{b as __pageData,f as default};
